import { useId, useRef, type KeyboardEvent, type ReactNode } from "react";
import "./TabStrip.css";

export interface Tab {
  id: string;
  label: string;
}

export interface TabStripProps {
  tabs: readonly Tab[];
  selected: string;
  onSelect: (id: string) => void;
  children: ReactNode;
}

export function TabStrip({ tabs, selected, onSelect, children }: TabStripProps) {
  const baseId = useId();
  const buttonRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const selectedIndex = tabs.findIndex((tab) => tab.id === selected);
  const activeIndex = selectedIndex === -1 ? 0 : selectedIndex;
  const activeTab = tabs[activeIndex];

  const panelId = `${baseId}-panel`;
  const tabDomId = (index: number) => `${baseId}-tab-${index}`;

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const count = tabs.length;
    let next: number;

    switch (event.key) {
      case "ArrowRight":
        next = (index + 1) % count;
        break;
      case "ArrowLeft":
        next = (index - 1 + count) % count;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = count - 1;
        break;
      default:
        return;
    }

    event.preventDefault();

    const target = tabs[next];
    if (!target) {
      return;
    }

    onSelect(target.id);
    buttonRefs.current[next]?.focus();
  }

  return (
    <div className="tab-strip">
      <div role="tablist" className="tab-strip__list">
        {tabs.map((tab, index) => {
          const isSelected = index === activeIndex;

          return (
            <button
              key={tab.id}
              ref={(element) => {
                buttonRefs.current[index] = element;
              }}
              id={tabDomId(index)}
              type="button"
              role="tab"
              className="tab-strip__tab"
              aria-selected={isSelected}
              aria-controls={panelId}
              tabIndex={isSelected ? 0 : -1}
              onClick={() => onSelect(tab.id)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {tab.label}
            </button>
          );
        })}
      </div>

      <div
        role="tabpanel"
        id={panelId}
        className="tab-strip__panel"
        aria-labelledby={activeTab ? tabDomId(activeIndex) : undefined}
        tabIndex={0}
      >
        {children}
      </div>
    </div>
  );
}
