.tab-strip {
  display: flex;
  flex-direction: column;
  gap: clamp(0.75rem, 1.5vw, 1.25rem);
  color: var(--ink);
  font: inherit;
}

.tab-strip__list {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(0.25rem, 0.8vw, 0.75rem);
  border-bottom: 1px solid var(--hair);
}

.tab-strip__tab {
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1.05rem);
  color: var(--muted);
  background: transparent;
  border: 0;
  border-bottom: 3px solid transparent;
  margin-bottom: -1px;
  padding: 0.5em 0.9em;
  cursor: pointer;
  white-space: nowrap;
  transition: color 150ms ease, border-color 150ms ease;
}

.tab-strip__tab:hover {
  color: var(--ink);
}

.tab-strip__tab[aria-selected="true"] {
  color: var(--myelin);
  font-weight: 600;
  border-bottom-color: var(--myelin);
}

.tab-strip__panel {
  color: var(--ink);
}

:root[data-motion="reduce"] .tab-strip__tab {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .tab-strip__tab {
    transition: none;
  }
}
